LESSONS = [
 T(277,"deferred-foreign-key","延迟外键允许事务内先子后父",["DEFERRABLE","延迟约束","事务一致性"],
   "DEFERRABLE INITIALLY DEFERRED 把外键检查推迟到事务提交。事务先插 child(10,1)，再插 parent(1)，提交时引用完整，最终连接得到 10、1。它不是关闭外键，若提交仍缺父记录就必须失败。",
   "PRAGMA foreign_keys=ON; CREATE TABLE parent(id INTEGER PRIMARY KEY); CREATE TABLE child(id INTEGER PRIMARY KEY,parent_id INTEGER REFERENCES parent(id) DEFERRABLE INITIALLY DEFERRED); BEGIN; INSERT INTO child VALUES(10,1); INSERT INTO parent VALUES(1); COMMIT;",
   "SELECT c.id,p.id FROM child c JOIN parent p ON p.id=c.parent_id ORDER BY c.id;","10|1",
   ["foreign_keys 必须在事务外启用。","延迟检查仍会在提交时拒绝未满足引用。"],
   ("检查是否有外键违规。","PRAGMA foreign_key_check 返回违规行。","PRAGMA foreign_key_check;","(no rows)"),
   ("统计成功提交的子记录数。","COUNT child。","SELECT count(*) FROM child;","1")),
 T(278,"foreign-key-update-cascade","业务键更改通过外键级联更新",["ON UPDATE CASCADE","引用键更新","完整性"],
   "父表 code 从 A 改为 A2，ON UPDATE CASCADE 自动更新子表引用，所以子记录无需应用手工补写。真实系统更常使用稳定代理键，但迁移已有自然键时，数据库级级联能保证同一语句的一致性。",
   "PRAGMA foreign_keys=ON; CREATE TABLE category(code TEXT PRIMARY KEY); CREATE TABLE item(id INTEGER PRIMARY KEY,category TEXT REFERENCES category(code) ON UPDATE CASCADE); INSERT INTO category VALUES('A'); INSERT INTO item VALUES(1,'A'),(2,'A'); UPDATE category SET code='A2' WHERE code='A';",
   "SELECT id,category FROM item ORDER BY id;","1|A2\n2|A2",
   ["引用目标必须有匹配的主键或唯一约束。","级联更新不是跨数据库迁移的通用替代。"],
   ("返回更新后的父键。","查询 category。","SELECT code FROM category ORDER BY code;","A2"),
   ("验证不存在旧引用 A。","统计旧键。","SELECT count(*) FROM item WHERE category='A';","0")),
 T(279,"self-reference-set-null","删除经理时保留员工并清空引用",["自引用外键","ON DELETE SET NULL","层级变更"],
   "员工表的 manager 引用同表 id，删除经理 1 后，员工 2、3 仍存在，manager 自动设为 NULL。SET NULL 适合保留独立实体，但若 manager 列声明 NOT NULL 就与策略冲突；它不同于删除整棵子树。",
   "PRAGMA foreign_keys=ON; CREATE TABLE employee(id INTEGER PRIMARY KEY,name TEXT,manager INTEGER REFERENCES employee(id) ON DELETE SET NULL); INSERT INTO employee VALUES(1,'Lead',NULL),(2,'Ann',1),(3,'Bob',1); DELETE FROM employee WHERE id=1;",
   "SELECT id,name,coalesce(manager,-1) FROM employee ORDER BY id;","2|Ann|-1\n3|Bob|-1",
   ["SET NULL 需要引用列允许 NULL。","删除经理不意味着应删除员工实体。"],
   ("统计经理为空的剩余员工。","manager IS NULL。","SELECT count(*) FROM employee WHERE manager IS NULL;","2"),
   ("检查删除后仍无外键违规。","foreign_key_check 应为空。","PRAGMA foreign_key_check;","(no rows)")),
 T(280,"tenant-composite-reference","租户隔离用复合外键约束",["复合外键","多租户","复合主键"],
   "同一 code 在不同租户可重复，子表必须同时引用 tenant、code。两个租户都有 A，任务 1 属于租户 1，任务 2 属于租户 2，连接也必须带完整复合键，否则会把每个任务配给两个客户。",
   "PRAGMA foreign_keys=ON; CREATE TABLE customer(tenant INTEGER,code TEXT,label TEXT,PRIMARY KEY(tenant,code)); CREATE TABLE task(id INTEGER PRIMARY KEY,tenant INTEGER,customer_code TEXT,FOREIGN KEY(tenant,customer_code) REFERENCES customer(tenant,code)); INSERT INTO customer VALUES(1,'A','North'),(2,'A','South'); INSERT INTO task VALUES(1,1,'A'),(2,2,'A');",
   "SELECT t.id,c.label FROM task t JOIN customer c ON c.tenant=t.tenant AND c.code=t.customer_code ORDER BY t.id;","1|North\n2|South",
   ["只用 code 连接会破坏租户边界。","复合引用中某列允许 NULL 时可能绕过部分检查。"],
   ("演示遗漏租户条件会产生多少连接行。","只连接 code 用作错误示例对照。","SELECT count(*) FROM task t JOIN customer c ON c.code=t.customer_code;","4"),
   ("每租户统计任务数。","按 task.tenant 聚合。","SELECT tenant,count(*) FROM task GROUP BY tenant ORDER BY tenant;","1|1\n2|1")),
 T(281,"soft-delete-active-unique","软删除记录的部分唯一索引",["部分唯一索引","软删除","活动键"],
   "唯一索引只覆盖 deleted_at IS NULL 的活动记录，历史删除行可保留相同邮箱。插入活动 Ann 后，OR IGNORE 拒绝第二个活动重复，但不删除历史记录。这样唯一规则与业务活动状态一致。",
   "CREATE TABLE contact(id INTEGER PRIMARY KEY,email TEXT NOT NULL,deleted_at TEXT); CREATE UNIQUE INDEX active_email ON contact(email) WHERE deleted_at IS NULL; INSERT INTO contact VALUES(1,'ann@example.com','2026-01-01'),(2,'ann@example.com',NULL); INSERT OR IGNORE INTO contact VALUES(3,'ann@example.com',NULL);",
   "SELECT id,email,deleted_at IS NULL active FROM contact ORDER BY id;","1|ann@example.com|0\n2|ann@example.com|1",
   ["恢复历史行也要经过活动唯一约束。","OR IGNORE 会跳过错误，应检查是否真正写入。"],
   ("统计活动联系人数量。","deleted_at IS NULL。","SELECT count(*) FROM contact WHERE deleted_at IS NULL;","1"),
   ("查询被忽略的 id=3 是否存在。","COUNT 验证插入结果。","SELECT count(*) FROM contact WHERE id=3;","0")),
 T(282,"expression-unique-key","表达式唯一索引统一规范业务键",["表达式索引","LOWER TRIM","唯一性"],
   "在 LOWER(TRIM(email)) 上建立唯一索引，保留原始输入的同时约束规范键。先插入带空格大写地址，再插小写相同地址被忽略，只剩第一行。规范化只涵盖既定 ASCII 规则，不声称全 Unicode 邮箱等价。",
   "CREATE TABLE login(id INTEGER PRIMARY KEY,email TEXT NOT NULL); CREATE UNIQUE INDEX canonical_login ON login(lower(trim(email))); INSERT INTO login VALUES(1,' ANN@example.com '); INSERT OR IGNORE INTO login VALUES(2,'ann@example.com');",
   "SELECT id,email FROM login ORDER BY id;","1| ANN@example.com",
   ["规范化规则必须稳定，改变规则可能导致冲突。","查询需使用匹配表达式以利用表达式索引。"],
   ("输出保存的规范业务键。","LOWER(TRIM(email))。","SELECT lower(trim(email)) FROM login;","ann@example.com"),
   ("统计真实保留行数。","忽略冲突没有生成第二行。","SELECT count(*) FROM login;","1")),
 T(283,"trigger-update-audit","更新触发器记录 OLD 与 NEW",["AFTER UPDATE","审计日志","OLD NEW"],
   "AFTER UPDATE OF balance 在余额改变时记录旧新值，WHEN 用 IS NOT 避免无变化更新写入假审计。账户从 100 改为 130 后只有一条日志；再次设成 130 不增加日志。触发器运行于同一数据库事务，回滚会一起撤销。",
   "CREATE TABLE account(id INTEGER PRIMARY KEY,balance INTEGER); CREATE TABLE audit(id INTEGER PRIMARY KEY,account_id INTEGER,old_value INTEGER,new_value INTEGER); CREATE TRIGGER account_changed AFTER UPDATE OF balance ON account WHEN old.balance IS NOT new.balance BEGIN INSERT INTO audit(account_id,old_value,new_value) VALUES(new.id,old.balance,new.balance); END; INSERT INTO account VALUES(1,100); UPDATE account SET balance=130 WHERE id=1; UPDATE account SET balance=130 WHERE id=1;",
   "SELECT account_id,old_value,new_value FROM audit ORDER BY id;","1|100|130",
   ["审计触发器不是不可篡改安全日志。","WHEN 可避免无变化更新产生噪声。"],
   ("统计真实变化次数。","COUNT audit。","SELECT count(*) FROM audit;","1"),
   ("核对余额总变化。","日志新减旧。","SELECT sum(new_value-old_value) FROM audit;","30")),
 T(284,"writable-view-trigger","INSTEAD OF 触发器使视图写入生效",["视图写入","INSTEAD OF","边界封装"],
   "SQLite 普通视图不能直接写入；INSTEAD OF INSERT 将视图输入映射到底层表，同时把姓名规范为 TRIM 值。通过视图插入带空格 Ann，底层保存 Ann。视图只暴露需要的字段，但不是数据库访问权限系统。",
   "CREATE TABLE person(id INTEGER PRIMARY KEY,name TEXT NOT NULL); CREATE VIEW entry AS SELECT id,name FROM person; CREATE TRIGGER entry_insert INSTEAD OF INSERT ON entry BEGIN INSERT INTO person(id,name) VALUES(new.id,trim(new.name)); END; INSERT INTO entry VALUES(1,' Ann ');",
   "SELECT id,name FROM person ORDER BY id;","1|Ann",
   ["INSTEAD OF 触发器只替代定义的事件，不自动覆盖 UPDATE DELETE。","触发器中的约束错误仍应反馈调用方。"],
   ("通过视图读取规范姓名。","视图查询底层实时数据。","SELECT name FROM entry ORDER BY id;","Ann"),
   ("核对底层姓名已无首尾空格。","比较 name 与 trim(name)。","SELECT name=trim(name) FROM person;","1")),
 T(285,"revision-guarded-upsert","用版本条件拒绝旧快照覆盖",["UPSERT WHERE","版本号","乐观合并"],
   "UPSERT 冲突更新只在 excluded.rev 大于当前 rev 时发生。初始版本 2，旧版本 1 被忽略，版本 3 成功覆盖为 fresh。它适合离线同步的单记录合并，但跨记录一致性和真实并发仍需事务与冲突反馈。",
   "CREATE TABLE snapshot(id INTEGER PRIMARY KEY,rev INTEGER NOT NULL,payload TEXT); INSERT INTO snapshot VALUES(1,2,'current'); INSERT INTO snapshot VALUES(1,1,'stale') ON CONFLICT(id) DO UPDATE SET rev=excluded.rev,payload=excluded.payload WHERE excluded.rev>snapshot.rev; INSERT INTO snapshot VALUES(1,3,'fresh') ON CONFLICT(id) DO UPDATE SET rev=excluded.rev,payload=excluded.payload WHERE excluded.rev>snapshot.rev;",
   "SELECT id,rev,payload FROM snapshot ORDER BY id;","1|3|fresh",
   ["版本比较规则必须来自可信写入协议。","未更新并不自动代表操作成功，应返回冲突状态。"],
   ("检查旧快照是否残留。","查询 payload='stale'。","SELECT count(*) FROM snapshot WHERE payload='stale';","0"),
   ("返回保存的最高版本号。","MAX(rev)。","SELECT max(rev) FROM snapshot;","3")),
 T(286,"update-from-preaggregate","UPDATE FROM 先消除多重匹配",["UPDATE FROM","预聚合","确定更新"],
   "调整表同一商品可有多条增减，先按 sku 求和，再 UPDATE FROM 一商品一行来源。A 原 10 调整 -2-3 后为 5，B 原 5 加 1 为 6。若直接连接多条来源，目标行到底使用哪条匹配可能不确定。",
   "CREATE TABLE stock(sku TEXT PRIMARY KEY,qty INTEGER); INSERT INTO stock VALUES('A',10),('B',5); CREATE TABLE adjustment(sku TEXT,delta INTEGER); INSERT INTO adjustment VALUES('A',-2),('A',-3),('B',1); UPDATE stock SET qty=stock.qty+a.delta FROM(SELECT sku,sum(delta) delta FROM adjustment GROUP BY sku) a WHERE a.sku=stock.sku;",
   "SELECT sku,qty FROM stock ORDER BY sku;","A|5\nB|6",
   ["来源多重匹配不能当作多次累加更新。","重跑同一调整会重复应用，需要额外幂等标记。"],
   ("核对全部调整净变化。","SUM adjustment.delta。","SELECT sum(delta) FROM adjustment;","-4"),
   ("核对更新后总库存。","原 15 加净变化 -4。","SELECT sum(qty) FROM stock;","11")),
 T(287,"delete-anti-reference","只清理未被引用的临时实体",["DELETE NOT EXISTS","引用保护","定向清理"],
   "临时标签 1 被文档引用，2 未引用，3 为永久标签。DELETE 仅作用于 temporary=1 且不存在引用的标签，因此只删 2，保留 1、3。清理条件同时描述实体类别与引用情况，避免按时间一刀切删除。",
   "CREATE TABLE tag(id INTEGER PRIMARY KEY,temporary INTEGER); CREATE TABLE document_tag(document_id INTEGER,tag_id INTEGER); INSERT INTO tag VALUES(1,1),(2,1),(3,0); INSERT INTO document_tag VALUES(10,1); DELETE FROM tag WHERE temporary=1 AND NOT EXISTS(SELECT 1 FROM document_tag r WHERE r.tag_id=tag.id);",
   "SELECT id,temporary FROM tag ORDER BY id;","1|1\n3|0",
   ["实际删除仍应在事务中配合外键保护。","NOT IN 若子查询含 NULL 可能让清理失效。"],
   ("统计剩余临时标签数。","temporary=1。","SELECT count(*) FROM tag WHERE temporary=1;","1"),
   ("验证永久标签 3 被保留。","查询该 id。","SELECT temporary FROM tag WHERE id=3;","0")),
 T(288,"stored-generated-recalculation","存储生成列随基础字段重新计算",["GENERATED STORED","派生金额","UPDATE"],
   "line_total 定义为 qty×unit 的 STORED 生成列，插入时得到 600，qty 改为 4 后自动变为 800。应用只写基础字段，不能直接给生成列赋值，从结构上避免明细金额与数量价格不一致。",
   "CREATE TABLE line(id INTEGER PRIMARY KEY,qty INTEGER NOT NULL,unit INTEGER NOT NULL,line_total INTEGER GENERATED ALWAYS AS(qty*unit) STORED); INSERT INTO line(id,qty,unit) VALUES(1,3,200); UPDATE line SET qty=4 WHERE id=1;",
   "SELECT id,qty,unit,line_total FROM line ORDER BY id;","1|4|200|800",
   ["生成表达式不能使用任意非确定函数或子查询。","STORED 列与普通列的迁移能力不同，应先查引擎规则。"],
   ("核对生成列等于基础字段表达式。","直接比较。","SELECT line_total=qty*unit FROM line;","1"),
   ("查询生成列的隐藏标记。","table_xinfo 包含生成列元数据。","SELECT name,hidden FROM pragma_table_xinfo('line') WHERE name='line_total';","line_total|3")),
 T(289,"without-rowid-composite-key","WITHOUT ROWID 的复合主键存储契约",["WITHOUT ROWID","复合主键","非空键"],
   "WITHOUT ROWID 表以 tenant、code 复合主键组织数据，不提供隐式 rowid，主键列也不允许 NULL。查询必须使用显式业务键，便于离线编辑器避免假设每张表都有 rowid。本例按完整主键稳定排序。",
   "CREATE TABLE dictionary(tenant INTEGER,code TEXT,value TEXT,PRIMARY KEY(tenant,code)) WITHOUT ROWID; INSERT INTO dictionary VALUES(1,'B','two'),(1,'A','one'),(2,'A','other');",
   "SELECT tenant,code,value FROM dictionary ORDER BY tenant,code;","1|A|one\n1|B|two\n2|A|other",
   ["依赖 rowid 的通用编辑逻辑在此类表上不可用。","主键列位置与非空性应从真实元数据读取。"],
   ("返回复合主键各列顺序。","table_info.pk 为从一开始的位置。","SELECT name,pk FROM pragma_table_info('dictionary') WHERE pk>0 ORDER BY pk;","tenant|1\ncode|2"),
   ("核对 table_list 的 WITHOUT ROWID 标记。","wr=1。","SELECT wr FROM pragma_table_list WHERE name='dictionary' AND schema='main';","1")),
 T(290,"strict-affinity-contract","STRICT 表仍有明确的无损转换规则",["STRICT","类型约束","无损转换"],
   "STRICT 的 INTEGER 列允许把文本 '12' 无损转换为整数，TEXT 列将数值 34 存为文本。TYPEOF 显示 integer、text，说明严格表是约束存储类型，不是禁止一切输入转换；不可无损转换的输入会被拒绝。",
   "CREATE TABLE sample(id INTEGER PRIMARY KEY,n INTEGER,label TEXT) STRICT; INSERT INTO sample VALUES(1,'12',34);",
   "SELECT n,typeof(n),label,typeof(label) FROM sample;","12|integer|34|text",
   ["STRICT 不代替业务范围与格式 CHECK。","STRICT 的 ANY 与普通表亲和性有不同保留行为。"],
   ("读取表的 strict 元数据标记。","pragma_table_list.strict。","SELECT strict FROM pragma_table_list WHERE schema='main' AND name='sample';","1"),
   ("核对存储整数的算术结果。","n+1。","SELECT n+1 FROM sample;","13")),
 T(291,"catalog-schema-inventory","从真实 schema 清点表视图和显式索引",["sqlite_schema","对象清单","内部对象"],
   "sqlite_schema 保存对象类型、名字与所属表。排除 sqlite_ 内部对象后，清单有显式索引、数据表和视图，触发器也可用相同方式列出。元数据来自引擎而非 UI 猜测，用户自建对象的结构工具应依此展示。",
   "CREATE TABLE note(id INTEGER PRIMARY KEY,title TEXT); CREATE INDEX note_title ON note(title); CREATE VIEW note_names AS SELECT id,title FROM note; INSERT INTO note VALUES(1,'local');",
   "SELECT type,name,tbl_name FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name;","index|note_title|note\ntable|note|note\nview|note_names|note_names",
   ["内置自动索引与用户显式索引应区分。","sqlite_schema.sql 是结构文本，不能当作完整 SQL 解析器。"],
   ("列出 note 的显式索引名。","pragma_index_list 返回真实索引元数据。","SELECT name FROM pragma_index_list('note') WHERE origin='c' ORDER BY name;","note_title"),
   ("从视图读取真实数据。","视图不是复制表。","SELECT id,title FROM note_names ORDER BY id;","1|local")),
]
